examples.template:
CompositionLocalProvider(LocalConfiguration provides locale) {
    @OptIn(ExperimentalMonarchApi::class)
    MonarchTimeOffPanel(
        entries = entries,
        onAdd = { draft ->
            entries = entries + MonarchTimeOffEntry(
                id = draft.start.toString(),
                personId = draft.personId,
                allDay = draft.allDay,
                start = draft.start,
                end = draft.end,
                reason = draft.reason,
            )
        },
        onRemove = { entry -> entries = entries - entry },
        people = listOf(MonarchSelectOption({{people.0.value}}, {{people.0.label}}), MonarchSelectOption({{people.1.value}}, {{people.1.label}})),
        allowClosure = true,
        is24Hour = true,
        timeZone = {{timeZone}},
        now = {{now|millis}},
    )
}

examples.setupTemplate:
var entries by remember {
    mutableStateOf(
        listOf(
            MonarchTimeOffEntry(id = "1", personId = {{entries.0.personId}}, allDay = {{entries.0.allDay}}, start = {{entries.0.start|millis}}, end = {{entries.0.end|millis}}, personName = {{entries.0.personName}}, type = {{entries.0.type}}),
            MonarchTimeOffEntry(id = "2", personId = null, allDay = {{entries.1.allDay}}, start = {{entries.1.start|millis}}, end = {{entries.1.end|millis}}, reason = {{entries.1.reason}}),
            MonarchTimeOffEntry(id = "3", personId = {{entries.2.personId}}, allDay = {{entries.2.allDay}}, start = {{entries.2.start|millis}}, end = {{entries.2.end|millis}}, personName = {{entries.2.personName}}, reason = {{entries.2.reason}}),
            MonarchTimeOffEntry(id = "4", personId = {{entries.3.personId}}, allDay = {{entries.3.allDay}}, start = {{entries.3.start|millis}}, end = {{entries.3.end|millis}}, personName = {{entries.3.personName}}),
        ),
    )
}
val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}

